def ts(text, st, end):
    assert len(text)==len(st), (len(text),len(st),text)
    assert all(a<=b for a,b in zip(st,st[1:]))
    return [{"characters":list(text),"character_start_times_seconds":st,"character_end_times_seconds":st[1:]+[end]}]
OUT={k:{"voice":u,"timestamps":ts(t,s,e),"narration":t.strip()} for k,u,t,s,e in V}
if __name__=="__main__":
    for k,v in OUT.items(): print(k, v["timestamps"][0]["character_end_times_seconds"][-1], v["narration"])
